// Every piece of interface text, in English and Arabic.
// Plurals: an object keyed by Intl.PluralRules categories (zero, one, two, few, many, other).
export type Lang = 'en' | 'ar';
type Entry = string | Record<string, string>;

const en1 = (one: string, other: string, zero?: string): Entry => (zero ? { zero, one, other } : { one, other });
// Arabic: 1, 2, 3–10, 11–99, 100+ (and the zero form when given).
const ar = (one: string, two: string, few: string, many: string, zero?: string): Entry => ({ ...(zero ? { zero } : {}), one, two, few, many, other: many });

